package com.dentalclinic.odontogram;
import com.dentalclinic.odontogram.service.*;
import com.dentalclinic.odontogram.dto.*;
import com.dentalclinic.odontogram.controller.OdontogramConditionController;
import com.dentalclinic.clinic.entity.Clinic;
import com.dentalclinic.user.entity.AppUser;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.test.context.DynamicPropertyRegistry;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties="spring.jpa.show-sql=false")
@EnabledIfEnvironmentVariable(named="ODONTOGRAM_TEST_DATABASE",matches="true")
class OdontogramConfigurationDatabaseTest {
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){String u=System.getenv("SPRING_DATASOURCE_URL");if(u==null||!u.matches("jdbc:postgresql://localhost:5432/dental_clinic_v21_verification_[a-z0-9_]+"))throw new IllegalStateException("Disposable local database required");r.add("spring.datasource.url",()->u);}
 @Autowired JdbcTemplate db; @Autowired OdontogramConfigurationService service; @Autowired OdontogramConditionController controller;
 @Autowired OdontogramService observations; @Autowired javax.sql.DataSource dataSource;
 UUID clinic,actor; AppUser user;
 @BeforeEach void setup(){clinic=UUID.randomUUID();actor=UUID.randomUUID();db.update("insert into clinic(id,clinic_code,clinic_name) values (?,?,'Configuration test')",clinic,clinic.toString());db.update("insert into app_user(id,clinic_id,first_name) values (?,?,'Test')",actor,clinic);user=AppUser.builder().id(actor).clinic(Clinic.builder().id(clinic).active(true).build()).build();login("ODONTOGRAM_CONFIGURE","ODONTOGRAM_VIEW");}
 void login(String...permissions){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(user,null,Arrays.stream(permissions).map(SimpleGrantedAuthority::new).toList()));}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 CreateOdontogramConditionRequest request(String name){var r=new CreateOdontogramConditionRequest();r.setClinicId(clinic);r.setConditionName(name);r.setColourHex("#123456");return r;}
 UpdateOdontogramConditionRequest update(String name,boolean active,boolean terminology){return new UpdateOdontogramConditionRequest(name,"Description","#abcdef",active,terminology);}
 @Test void newClinicDefaultsAreIdempotentAndRespectCustomization(){assertEquals(9,service.list(clinic,true).size());var first=service.list(clinic,true).get(0);service.update(first.id(),clinic,"\"0\"",new UpdateOdontogramConditionRequest(first.conditionName(),null,"#010203",false,false));db.queryForObject("select initialize_odontogram_conditions(?)",Object.class,clinic);assertEquals(9,service.list(clinic,true).size());assertEquals("#010203",service.get(first.id(),clinic).colourHex());assertFalse(service.get(first.id(),clinic).active());}
 @Test void namesUniqueOnlyAmongActiveAndCodesStable(){var a=service.create(request("Custom"));assertThrows(OdontogramMutationException.class,()->service.create(request(" custom ")));service.update(a.id(),clinic,"\"0\"",update("Custom",false,false));assertNotNull(service.create(request("Custom")));assertThrows(OdontogramMutationException.class,()->service.update(a.id(),clinic,"\"1\"",update("Custom",true,false)));assertEquals(a.conditionCode(),service.get(a.id(),clinic).conditionCode());}
 @Test void renameRequiresTerminologyConfirmationAndVersions(){var a=service.create(request("Original"));assertEquals(428,assertThrows(OdontogramMutationException.class,()->service.update(a.id(),clinic,null,update("Original",true,false))).status);assertEquals(400,assertThrows(OdontogramMutationException.class,()->service.update(a.id(),clinic,"0",update("Original",true,false))).status);assertEquals(409,assertThrows(OdontogramMutationException.class,()->service.update(a.id(),clinic,"\"0\"",update("Corrected",true,false))).status);assertEquals(1,service.update(a.id(),clinic,"\"0\"",update("Corrected",true,true)).version());assertEquals(412,assertThrows(OdontogramMutationException.class,()->service.update(a.id(),clinic,"\"0\"",update("Other",true,true))).status);}
 @Test void permissionsAndClinicIsolation(){var a=service.create(request("Private"));login("ODONTOGRAM_VIEW");assertThrows(org.springframework.security.access.AccessDeniedException.class,()->controller.getConditions(clinic,true));assertThrows(org.springframework.security.access.AccessDeniedException.class,()->controller.createCondition(request("Denied")));assertFalse(controller.getConditions(clinic,false).isEmpty());UUID other=UUID.randomUUID();db.update("insert into clinic(id,clinic_code,clinic_name) values (?,?,'Other')",other,other.toString());var original=user;user=AppUser.builder().id(actor).clinic(Clinic.builder().id(other).active(true).build()).build();login("ODONTOGRAM_CONFIGURE");assertEquals(404,assertThrows(OdontogramMutationException.class,()->service.get(a.id(),other)).status);user=original;}
 @Test void historySnapshotSurvivesRenameDeactivateAndColourChange(){var a=service.create(request("Observed"));UUID patient=UUID.randomUUID(),chart=UUID.randomUUID(),tooth=UUID.randomUUID(),event=UUID.randomUUID();db.update("insert into patient(id,clinic_id,patient_number,first_name,gender,phone) values (?,?,?,'Test','OTHER','123')",patient,clinic,patient.toString());db.update("insert into odontogram(id,clinic_id,patient_id) values (?,?,?)",chart,clinic,patient);db.update("insert into odontogram_tooth(id,clinic_id,odontogram_id,tooth_number,condition_id) values (?,?,?,'46',?)",tooth,clinic,chart,a.id());db.update("insert into odontogram_tooth_history(id,clinic_id,odontogram_id,odontogram_tooth_id,tooth_number,new_condition_id,changed_by) values (?,?,?,?,'46',?,?)",event,clinic,chart,tooth,a.id(),actor);
 String original=db.queryForObject("select row_to_json(h)::text from odontogram_tooth_history h where id=?",String.class,event);service.update(a.id(),clinic,"\"0\"",update("Observed terminology corrected",false,true));var h=observations.getToothHistory(chart,"46",clinic).get(0);assertEquals("Observed",h.getNewConditionName());assertEquals("EVENT_TIME",h.getLabelSource());assertEquals(a.id(),observations.getTeeth(chart,clinic).get(0).getConditionId());assertEquals(0,observations.getTeeth(chart,clinic).get(0).getVersion());assertEquals(original,db.queryForObject("select row_to_json(h)::text from odontogram_tooth_history h where id=?",String.class,event));assertThrows(Exception.class,()->db.update("delete from odontogram_condition where id=?",a.id()));assertThrows(Exception.class,()->db.update("update odontogram_history_label set new_name='bad' where history_id=?",event));}
 @Test void auditPreservedAndFailedUpdateRollsBack(){var a=service.create(request("Audit"));int before=db.queryForObject("select count(*) from odontogram_configuration_audit where condition_id=?",Integer.class,a.id());assertThrows(Exception.class,()->service.update(a.id(),clinic,"\"0\"",new UpdateOdontogramConditionRequest("Changed",null,"invalid",true,true)));assertEquals("Audit",service.get(a.id(),clinic).conditionName());assertEquals(before,db.queryForObject("select count(*) from odontogram_configuration_audit where condition_id=?",Integer.class,a.id()));assertThrows(Exception.class,()->db.update("delete from odontogram_configuration_audit where condition_id=?",a.id()));}
 @Test void concurrentEditorsCannotOverwrite() throws Exception {var a=service.create(request("Concurrent"));var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var jobs=new ArrayList<Future<Integer>>();for(int i=0;i<2;i++)jobs.add(pool.submit(()->{login("ODONTOGRAM_CONFIGURE");start.await();try{service.update(a.id(),clinic,"\"0\"",update("Concurrent",true,false));return 200;}catch(OdontogramMutationException e){return e.status;}finally{clear();}}));start.countDown();var codes=new ArrayList<Integer>();for(var job:jobs)codes.add(job.get(15,TimeUnit.SECONDS));Collections.sort(codes);assertEquals(List.of(200,412),codes);}finally{pool.shutdownNow();}}
 @Test void legacyMigrationPreservesHistoryAndMarksBaseline() throws Exception {String schema="cfg_"+UUID.randomUUID().toString().replace("-","");org.flywaydb.core.Flyway.configure().dataSource(dataSource).schemas(schema).defaultSchema(schema).target("21").load().migrate();
 try(var connection=dataSource.getConnection()){connection.setSchema(schema);var j=new JdbcTemplate(new org.springframework.jdbc.datasource.SingleConnectionDataSource(connection,true));UUID c=UUID.randomUUID(),u=UUID.randomUUID(),p=UUID.randomUUID(),o=UUID.randomUUID(),t=UUID.randomUUID(),h=UUID.randomUUID(),condition=UUID.randomUUID();j.update("insert into clinic(id,clinic_code,clinic_name) values (?,?,'Legacy')",c,c.toString());j.update("insert into app_user(id,clinic_id,first_name) values (?,?,'Legacy')",u,c);j.update("insert into patient(id,clinic_id,patient_number,first_name,gender,phone) values (?,?,?,'Test','OTHER','123')",p,c,p.toString());j.update("insert into odontogram(id,clinic_id,patient_id) values (?,?,?)",o,c,p);j.update("insert into odontogram_condition(id,clinic_id,condition_code,condition_name) values (?,?,'OLD','Legacy label')",condition,c);j.update("insert into odontogram_tooth(id,clinic_id,odontogram_id,tooth_number) values (?,?,?,'46')",t,c,o);j.update("insert into odontogram_tooth_history(id,clinic_id,odontogram_id,odontogram_tooth_id,tooth_number,new_condition_id,changed_by) values (?,?,?,?,'46',?,?)",h,c,o,t,condition,u);String before=j.queryForObject("select row_to_json(h)::text from odontogram_tooth_history h where id=?",String.class,h);org.flywaydb.core.Flyway.configure().dataSource(dataSource).schemas(schema).defaultSchema(schema).load().migrate();assertEquals(before,j.queryForObject("select row_to_json(h)::text from odontogram_tooth_history h where id=?",String.class,h));assertEquals("BASELINE",j.queryForObject("select source from odontogram_history_label where history_id=?",String.class,h));j.update("update odontogram_condition set condition_name='Corrected' where id=?",condition);assertEquals("Legacy label",j.queryForObject("select new_name from odontogram_history_label where history_id=?",String.class,h));assertEquals(10,j.queryForObject("select count(*) from odontogram_condition where clinic_id=?",Integer.class,c));connection.setSchema("public");}}

 @Test void platformContextAndColourVersion(){var c=service.create(request("Colour"));var r=new SaveOdontogramColourConfigRequest();r.setClinicId(clinic);r.setConditionId(c.id());r.setColourHex("#010101");r.setDisplayOrder(3);service.colourOnly(r,"\"0\"");assertEquals(1,service.get(c.id(),clinic).version());assertEquals(412,assertThrows(OdontogramMutationException.class,()->service.colourOnly(r,"\"0\"")).status);user=AppUser.builder().id(actor).build();login("ODONTOGRAM_CONFIGURE");assertThrows(IllegalArgumentException.class,()->controller.getConditions(null,true));assertFalse(controller.getConditions(clinic,true).isEmpty());}
 @Autowired org.springframework.web.context.WebApplicationContext web;
 @Test void httpValidationAndAuthorization() throws Exception {
 var mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.webAppContextSetup(web).build();
 String json="{\"conditionName\":\"Http\",\"colourHex\":\"invalid\"}";
 mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/odontogram-conditions").contentType("application/json").content(json)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isBadRequest());
 mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/odontogram-conditions").contentType("application/json").content(json.replace("Http"," ").replace("invalid","#123456"))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isBadRequest());
 login("ODONTOGRAM_EDIT");mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/odontogram-conditions").contentType("application/json").content(json.replace("invalid","#123456"))).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isForbidden());
 }
}
